#pragma once
#include "bridge_timeline.h"
#include <mutex>
#include <algorithm>
#include <memory>
namespace grs {namespace resource501 {
enum class Kind:uint32_t {Buffer=1,Texture,Program,Shader,VertexArray,Framebuffer,Sync};
enum class State:uint32_t {Free=0,Live,Retiring,Retired};
struct Object {uint64_t context=0,scope=0,name=0,generation=0,requestedBytes=0,ownerTid=0;Kind kind=Kind::Buffer;State state=State::Free;};
struct Event {uint64_t serial=0,ns=0,scope=0,context=0,name=0,generation=0,bytes=0,tid=0;uint32_t kind=0,error=0;std::array<char,32> phase{};};
struct Host {uintptr_t owner=0;uint64_t size=0,capacity=0,peak=0;std::array<char,40> category{};bool live=false;};
struct HostCategory {uint64_t size=0,capacity=0,peak=0,owners=0;std::array<char,40> name{};};
struct Exit {bool attempted=false,complete=false,shutdown=false;uint64_t scope=0,tid=0,display=0,surface=0,context=0,window=0;uint32_t error=0,firstError=0;std::array<char,40> stage{},firstStage{};};
struct Snapshot {
 std::array<Object,256> objects{};std::array<Host,64> hosts{};std::array<Event,256> events{};
 uint64_t serial=0,dropped=0,incomplete=0,creates=0,replaces=0,deletes=0,tombstones=0,retired=0,allocFailures=0,deallocFailures=0,liveBytes=0,retiringBytes=0,logicalPeak=0,hostPeak=0;
 Exit exit{};
 std::array<Exit,16> contextExits{};uint64_t exitScopes=0,exitDropped=0;
 uint64_t scope=0,context=0,ownerTid=0;std::array<char,40> phase{};std::array<HostCategory,32> hostCategories{};
 std::string Json()const{
  std::ostringstream o;o<<"{\"revision\":\"T501_OWNER_RESOURCE_LEDGER_V1\",\"gpuAccounting\":\"LOGICAL_REQUEST\",\"hostAccounting\":\"HOST_ALLOCATED_CAPACITY\",\"driverAccounting\":\"DRIVER_NOT_MEASURED\",\"driverRetiredBackingBytes\":\"NOT_MEASURED\",\"clock\":\"STEADY_NS\",\"liveBytes\":"<<liveBytes<<",\"retiringBytes\":"<<retiringBytes<<",\"logicalPeak\":"<<logicalPeak<<",\"hostPeak\":"<<hostPeak<<",\"creates\":"<<creates<<",\"replaces\":"<<replaces<<",\"deleteRequests\":"<<deletes<<",\"tombstones\":"<<tombstones<<",\"retired\":"<<retired<<",\"allocFailures\":"<<allocFailures<<",\"deallocFailures\":"<<deallocFailures<<",\"incomplete\":"<<incomplete<<",\"droppedEvents\":"<<dropped<<",\"objects\":[";
  bool comma=false;for(const auto& r:objects)if(r.state==State::Live||r.state==State::Retiring){if(comma)o<<',';comma=true;o<<"{\"scope\":\""<<r.scope<<"\",\"context\":\""<<r.context<<"\",\"ownerTid\":\""<<r.ownerTid<<"\",\"objectKind\":"<<uint32_t(r.kind)<<",\"name\":\""<<r.name<<"\",\"objectGeneration\":\""<<r.generation<<"\",\"requestedBytes\":"<<r.requestedBytes<<",\"state\":"<<uint32_t(r.state)<<'}';}
  o<<"],\"scope\":\""<<scope<<"\",\"context\":\""<<context<<"\",\"ownerTid\":\""<<ownerTid<<"\",\"phase\":\""<<phase.data()<<"\",\"hostCategories\":[";comma=false;for(const auto& h:hostCategories)if(h.name[0]){if(comma)o<<',';comma=true;o<<"{\"category\":\""<<h.name.data()<<"\",\"size\":"<<h.size<<",\"capacity\":"<<h.capacity<<",\"highWater\":"<<h.peak<<",\"owners\":"<<h.owners<<'}';}
  o<<"],\"host\":[";comma=false;for(const auto& h:hosts)if(h.owner){if(comma)o<<',';comma=true;o<<"{\"category\":\""<<h.category.data()<<"\",\"owner\":\""<<h.owner<<"\",\"size\":"<<h.size<<",\"capacity\":"<<h.capacity<<",\"highWater\":"<<h.peak<<",\"live\":"<<(h.live?"true":"false")<<'}';}
  o<<"],\"exit\":{\"attempted\":"<<(exit.attempted?"true":"false")<<",\"complete\":"<<(exit.complete?"true":"false")<<",\"shutdown\":"<<(exit.shutdown?"true":"false")<<",\"scope\":\""<<exit.scope<<"\",\"ownerTid\":\""<<exit.tid<<"\",\"stage\":\""<<exit.stage.data()<<"\",\"rawEgl\":"<<exit.error<<",\"firstStage\":\""<<exit.firstStage.data()<<"\",\"firstRawEgl\":"<<exit.firstError<<",\"display\":\""<<exit.display<<"\",\"surface\":\""<<exit.surface<<"\",\"context\":\""<<exit.context<<"\",\"heldWindow\":\""<<exit.window<<"\"},\"events\":[";
  const auto begin=serial>events.size()?serial-events.size():0;for(uint64_t i=begin;i<serial;++i){if(i!=begin)o<<',';const auto& e=events[i%events.size()];o<<"{\"serial\":\""<<e.serial<<"\",\"ns\":\""<<e.ns<<"\",\"scope\":\""<<e.scope<<"\",\"context\":\""<<e.context<<"\",\"ownerTid\":\""<<e.tid<<"\",\"phase\":\""<<e.phase.data()<<"\",\"objectKind\":"<<e.kind<<",\"name\":\""<<e.name<<"\",\"objectGeneration\":\""<<e.generation<<"\",\"requestedBytes\":"<<e.bytes<<",\"rawGl\":"<<e.error<<'}';}o<<"],\"exitDropped\":"<<exitDropped<<",\"contextExits\":[";comma=false;for(const auto& e:contextExits)if(e.attempted){if(comma)o<<',';comma=true;o<<"{\"scope\":\""<<e.scope<<"\",\"ownerTid\":\""<<e.tid<<"\",\"stage\":\""<<e.stage.data()<<"\",\"complete\":"<<(e.complete?"true":"false")<<",\"firstStage\":\""<<e.firstStage.data()<<"\",\"firstRawEgl\":"<<e.firstError<<",\"lastRawEgl\":"<<e.error<<'}';}o<<"]}";return o.str();
 }
};
class Ledger {
 std::mutex mutex;Snapshot data;uint64_t generation=0;
 void peak(){data.logicalPeak=std::max(data.logicalPeak,data.liveBytes+data.retiringBytes);}
 void event(const char* phase,const Object& r,uint32_t error=0){auto& e=data.events[data.serial%data.events.size()];e={};e.serial=++data.serial;e.ns=BridgeTimeline::Now();e.scope=r.scope;e.context=r.context;e.tid=BridgeTid();e.name=r.name;e.generation=r.generation;e.kind=uint32_t(r.kind);e.bytes=r.requestedBytes;e.error=error;std::strncpy(e.phase.data(),phase,e.phase.size()-1);if(data.serial>data.events.size())++data.dropped;}
 Object* find(uint64_t c,uint64_t s,Kind k,uint64_t n){for(auto& r:data.objects)if(r.context==c&&r.scope==s&&r.kind==k&&r.name==n&&(r.state==State::Live||r.state==State::Retiring))return &r;return nullptr;}
public:
 void Scope(uint64_t c,uint64_t s,const char* phase){std::lock_guard<std::mutex> lock(mutex);data.context=c;data.scope=s;data.ownerTid=BridgeTid();std::strncpy(data.phase.data(),phase,data.phase.size()-1);}
 Snapshot Copy(){std::lock_guard<std::mutex> lock(mutex);return data;}
 void Create(uint64_t c,uint64_t s,Kind k,uint64_t n,uint32_t error){std::lock_guard<std::mutex> lock(mutex);Object v;v.context=c;v.scope=s;v.kind=k;v.name=n;v.ownerTid=BridgeTid();if(error||!n){++data.allocFailures;event("CREATE_FAILED",v,error);return;}if(find(c,s,k,n)){++data.incomplete;return;}auto slot=std::find_if(data.objects.begin(),data.objects.end(),[](const Object& r){return r.state==State::Free||r.state==State::Retired;});if(slot==data.objects.end()||generation==UINT64_MAX){++data.incomplete;return;}v.generation=++generation;v.state=State::Live;*slot=v;++data.creates;event("CREATE",v);}
 void Allocate(uint64_t c,uint64_t s,Kind k,uint64_t n,uint64_t bytes,uint32_t error){std::lock_guard<std::mutex> lock(mutex);auto* r=find(c,s,k,n);if(error){++data.allocFailures;Object v;if(r)v=*r;v.requestedBytes=bytes;event("ALLOC_FAILED",v,error);return;}if(!r||r->state!=State::Live){++data.incomplete;return;}data.liveBytes-=r->requestedBytes;if(r->requestedBytes)++data.replaces;r->requestedBytes=bytes;data.liveBytes+=bytes;peak();event("ALLOC_OR_REPLACE",*r);}
 void Delete(uint64_t c,uint64_t s,Kind k,uint64_t n,uint32_t error){if(!n)return;std::lock_guard<std::mutex> lock(mutex);auto* r=find(c,s,k,n);if(error){++data.deallocFailures;Object v;if(r)v=*r;event("DELETE_FAILED",v,error);return;}if(!r)return;if(r->state==State::Live)data.liveBytes-=r->requestedBytes;else data.retiringBytes-=r->requestedBytes;r->state=State::Retired;++data.deletes;event("DELETE_NAME_REQUEST",*r);}
 void Tombstone(uint64_t c,uint64_t s){std::lock_guard<std::mutex> lock(mutex);for(auto& r:data.objects)if(r.context==c&&r.scope==s&&r.state==State::Live){r.state=State::Retiring;data.liveBytes-=r.requestedBytes;data.retiringBytes+=r.requestedBytes;++data.tombstones;event("TOMBSTONE",r);}peak();}
 void Retired(uint64_t c,uint64_t s){std::lock_guard<std::mutex> lock(mutex);for(auto& r:data.objects)if(r.context==c&&r.scope==s&&(r.state==State::Live||r.state==State::Retiring)){if(r.state==State::Live)data.liveBytes-=r.requestedBytes;else data.retiringBytes-=r.requestedBytes;r.state=State::Retired;++data.retired;event("CONTEXT_RETIRED",r);}}
 void HostStorage(const char* category,uintptr_t owner,uint64_t size,uint64_t capacity,bool live=true){std::lock_guard<std::mutex> lock(mutex);Host* slot=nullptr;for(auto& h:data.hosts)if(h.owner==owner&&std::strcmp(h.category.data(),category)==0){slot=&h;break;}if(!slot)for(auto& h:data.hosts)if(!h.owner||!h.live){slot=&h;*slot={};slot->owner=owner;std::strncpy(slot->category.data(),category,slot->category.size()-1);break;}if(!slot){++data.incomplete;return;}slot->size=size;slot->capacity=capacity;slot->live=live;slot->peak=std::max(slot->peak,capacity);HostCategory* cat=nullptr;for(auto& c:data.hostCategories)if(std::strcmp(c.name.data(),category)==0){cat=&c;break;}if(!cat)for(auto& c:data.hostCategories)if(!c.name[0]){cat=&c;std::strncpy(c.name.data(),category,c.name.size()-1);break;}if(!cat)++data.incomplete;for(auto& c:data.hostCategories)if(c.name[0]){c.size=c.capacity=c.owners=0;for(const auto& h:data.hosts)if(h.live&&h.category==c.name){c.size+=h.size;c.capacity+=h.capacity;++c.owners;}c.peak=std::max(c.peak,c.capacity);}uint64_t total=0;for(const auto& h:data.hosts)if(h.live)total+=h.capacity;data.hostPeak=std::max(data.hostPeak,total);}
 void ExitStage(const char* stage,uint64_t scope,bool shutdown,uint64_t d,uint64_t s,uint64_t c,uint64_t w,uint32_t error=0,bool complete=false){std::lock_guard<std::mutex> lock(mutex);data.scope=scope;data.context=c;data.ownerTid=BridgeTid();std::strncpy(data.phase.data(),stage,data.phase.size()-1);auto& e=data.exit;if(e.scope!=scope)e={};e.attempted=true;e.scope=scope;e.shutdown=shutdown;e.tid=BridgeTid();e.display=d;e.surface=s;e.context=c;e.window=w;e.error=error;e.complete=complete;std::strncpy(e.stage.data(),stage,e.stage.size()-1);if(error&&!e.firstError){e.firstError=error;std::strncpy(e.firstStage.data(),stage,e.firstStage.size()-1);}Exit* history=nullptr;for(auto& h:data.contextExits)if(h.attempted&&h.scope==scope){history=&h;break;}if(!history){history=&data.contextExits[data.exitScopes++%data.contextExits.size()];if(data.exitScopes>data.contextExits.size())++data.exitDropped;}*history=e;}
};
inline thread_local Ledger* current=nullptr;
inline thread_local uint64_t currentScope=0;
struct HostScope {Ledger* ledger;uintptr_t owner;const char* category;HostScope(Ledger* l,const char* name,const void* p,uint64_t size,uint64_t capacity):ledger(l),owner(reinterpret_cast<uintptr_t>(p)),category(name){if(ledger)ledger->HostStorage(category,owner,size,capacity);}HostScope(const char* name,const void* p,uint64_t size,uint64_t capacity):HostScope(current,name,p,size,capacity){}~HostScope(){if(ledger)ledger->HostStorage(category,owner,0,0,false);}};
}}
